"use client";

import { useState, type ReactNode } from "react";

type StockData = {
  error?: string;
  symbol: string;
  price: string | number;
  signal: string;
  rsi: string | number;
  momentum: string | number;
  atr: string | number;
  entry: string | number;
  stop_loss: string | number;
  target1: string | number;
  risk_reward: string | number;
  breakout: boolean;
  volume_spike: boolean;
};

export default function Home() {

  const [search, setSearch] = useState("");
  const [data, setData] = useState<StockData | null>(null);
  const [loading, setLoading] = useState(false);

  const searchStock = async () => {

    if (!search) return;

    setLoading(true);

    try {

      const res = await fetch(
        `http://127.0.0.1:8000/api/search/${search}`
      );

      const result = await res.json();

      console.log(result);

      setData(result);

    } catch (err) {

      console.error(err);

    }

    setLoading(false);
  };

  return (

    <main className="min-h-screen bg-black text-white p-10">

      <h1 className="text-4xl font-bold mb-8">
        AI Market Scanner
      </h1>

      {/* SEARCH BAR */}

      <div className="flex gap-4 mb-10">

        <input
          type="text"
          placeholder="Search stock..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="bg-zinc-900 border border-zinc-700 px-4 py-3 rounded-lg w-96"
        />

        <button
          onClick={searchStock}
          className="bg-green-600 hover:bg-green-500 px-6 py-3 rounded-lg font-semibold"
        >
          Search
        </button>

      </div>

      {/* LOADING */}

      {loading && (
        <p className="text-zinc-400">
          Loading...
        </p>
      )}

      {/* DATA */}

      {data && !data.error && (

        <div className="bg-zinc-900 p-8 rounded-2xl border border-zinc-800 w-full max-w-3xl">

          <div className="flex justify-between items-center">

            <div>
              <h2 className="text-3xl font-bold">
                {data.symbol}
              </h2>

              <p className="text-zinc-400 mt-2">
                Live AI Analysis
              </p>
            </div>

            <div className="text-right">

              <p className="text-4xl font-bold text-green-400">
                ₹{data.price}
              </p>

              <p className="mt-2 text-xl">
                {data.signal}
              </p>

            </div>

          </div>

          {/* GRID */}

          <div className="grid grid-cols-2 md:grid-cols-3 gap-6 mt-10">

            <Card title="RSI" value={data.rsi} />

            <Card title="Momentum" value={data.momentum} />

            <Card title="ATR" value={data.atr} />

            <Card title="Entry" value={data.entry} />

            <Card title="Stop Loss" value={data.stop_loss} />

            <Card title="Target" value={data.target1} />

            <Card title="RR Ratio" value={data.risk_reward} />

            <Card
              title="Breakout"
              value={data.breakout ? "YES" : "NO"}
            />

            <Card
              title="Volume Spike"
              value={data.volume_spike ? "YES" : "NO"}
            />

          </div>

        </div>

      )}

      {/* ERROR */}

      {data?.error && (

        <div className="bg-red-900/20 border border-red-700 p-6 rounded-xl">

          <p className="text-red-400">
            {data.error}
          </p>

        </div>

      )}

    </main>
  );
}

function Card({ title, value }: { title: string; value: ReactNode }) {

  return (

    <div className="bg-zinc-800 p-5 rounded-xl">

      <p className="text-zinc-400 text-sm">
        {title}
      </p>

      <p className="text-2xl font-bold mt-2">
        {value}
      </p>

    </div>
  );
}
